    items.sort(key=lambda it: it["kind"])
    unavailable.sort()

    checkout = (len(unavailable) == 0) and (recipient is not None)

    result = {
        "items": items,
        "total_cents": total_cents,
        "checkout": checkout,
        "recipient": recipient,
        "start": start,
        "unavailable": unavailable,
    }

    return {"name": contract["name"], "result": result}

