    unavailable = []

    for kind in sorted(wanted_by_kind):
        attrs = wanted_by_kind[kind]
        candidates = []
        for v in variants_by_kind.get(kind, []):
            if v["attributes"] == attrs and v["stock"] >= guest_count:
                candidates.append(v)
        if not candidates:
