import math


def _reject_nonfinite(obj):
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError("non-finite number")
        return obj
    if isinstance(obj, dict):
        return {k: _reject_nonfinite(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_reject_nonfinite(v) for v in obj]
    return obj


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")
    data = _unwrap(payloads[0])
    _reject_nonfinite(data)
    if not isinstance(data, dict):
        raise ValueError("input must be object")

    today = data["today"]
    weekday = data["weekday"]
    hour = data["hour"]
    guest_count = data["guest_count"]

    if isinstance(weekday, bool) or not isinstance(weekday, int):
        raise ValueError("weekday must be int")
    if not 0 <= weekday <= 6:
        raise ValueError("weekday out of range")
    if isinstance(hour, bool) or not isinstance(hour, int):
        raise ValueError("hour must be int")
    if not 0 <= hour <= 23:
        raise ValueError("hour out of range")
    if isinstance(guest_count, bool) or not isinstance(guest_count, int):
        raise ValueError("guest_count must be int")
    if guest_count < 1:
        raise ValueError("guest_count must be >= 1")

    import datetime
    d = datetime.date.fromisoformat(today)
    delta = (weekday - d.weekday()) % 7
    if delta == 0:
        delta = 7
    target = d + datetime.timedelta(days=delta)
    start = "%sT%02d:00" % (target.isoformat(), hour)

    return {"name": contract["name"], "result": {"start": start, "guest_count": guest_count}}

import math


def _reject_nonfinite(obj):
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError("non-finite number")
        return obj
    if isinstance(obj, dict):
        return {k: _reject_nonfinite(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_reject_nonfinite(v) for v in obj]
    return obj


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")
    data = _unwrap(payloads[0])
    _reject_nonfinite(data)
    if not isinstance(data, dict):
        raise ValueError("input must be object")

    conversations = data.get("conversations")
    topic = data.get("topic")
    if not isinstance(conversations, list):
        raise ValueError("conversations must be list")
    if not isinstance(topic, str):
        raise ValueError("topic must be string")

    needle = topic.casefold()
    best = None
    for conv in conversations:
        if not isinstance(conv, dict):
            raise ValueError("conversation must be object")
        cid = conv.get("id")
        contact_id = conv.get("contact_id")
        ts = conv.get("ts")
        ctopic = conv.get("topic")
        if not isinstance(ctopic, str):
            raise ValueError("conversation topic must be string")
        if needle not in ctopic.casefold():
            continue
        if best is None or ts > best[0] or (ts == best[0] and cid < best[1]):
            best = (ts, cid, contact_id)

    if best is None:
        result = {"contact_id": None, "conversation_id": None}
    else:
        result = {"contact_id": best[2], "conversation_id": best[1]}

    return {"name": contract["name"], "result": result}

import math


def _reject_nonfinite(obj):
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError("non-finite number")
        return obj
    if isinstance(obj, dict):
        return {k: _reject_nonfinite(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_reject_nonfinite(v) for v in obj]
    return obj


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")

    snapshot = _unwrap(payloads[0])
    dinner = _unwrap(payloads[1])
    contact = _unwrap(payloads[2])

    _reject_nonfinite(snapshot)
    _reject_nonfinite(dinner)
    _reject_nonfinite(contact)

    if not isinstance(snapshot, dict):
        raise ValueError("snapshot must be object")
    if not isinstance(dinner, dict):
        raise ValueError("dinner must be object")
    if not isinstance(contact, dict):
        raise ValueError("contact must be object")

    variants = snapshot["variants"]
    wanted = snapshot["wanted"]
    guest_count = dinner["guest_count"]
    start = dinner["start"]
    recipient = contact.get("contact_id")

    if not isinstance(variants, list):
        raise ValueError("variants must be list")
    if not isinstance(wanted, list):
        raise ValueError("wanted must be list")
    if isinstance(guest_count, bool) or not isinstance(guest_count, int):
        raise ValueError("guest_count must be int")
    if guest_count < 1:
        raise ValueError("guest_count must be >= 1")

    wanted_by_kind = {}
    for w in wanted:
        if not isinstance(w, dict):
            raise ValueError("wanted entry must be object")
        kind = w["kind"]
        if kind in wanted_by_kind:
            raise ValueError("duplicate kind in wanted")
        wanted_by_kind[kind] = w["attributes"]

    variants_by_kind = {}
    for v in variants:
        if not isinstance(v, dict):
            raise ValueError("variant must be object")
        kind = v["kind"]
        variants_by_kind.setdefault(kind, []).append(v)

    items = []
    total_cents = 0
    unavailable = []

    for kind in sorted(wanted_by_kind):
        attrs = wanted_by_kind[kind]
        candidates = []
        for v in variants_by_kind.get(kind, []):
            if v["attributes"] == attrs and v["stock"] >= guest_count:
                candidates.append(v)
        if not candidates:
            unavailable.append(kind)
            continue
        best = min(candidates, key=lambda v: (v["price_cents"], v["id"]))
        items.append({"id": best["id"], "kind": kind, "quantity": guest_count})
        total_cents += best["price_cents"] * guest_count

    items.sort(key=lambda it: it["kind"])
    unavailable.sort()

    checkout = (len(unavailable) == 0) and (recipient is not None)

    result = {
        "items": items,
        "total_cents": total_cents,
        "checkout": checkout,
        "recipient": recipient,
        "start": start,
        "unavailable": unavailable,
    }

    return {"name": contract["name"], "result": result}
